								<div class="absolute inset-y-0 left-0 flex items-center pl-2 scoreer-events-none">
									<svg class="w-3.5 h-3.5 text-gray-400" fill="none" stroke="currentColor"
										viewBox="0 0 24 24">
										<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
											d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
									</svg>
								</div>
							</div>
						</div>
					</div>
					<hr class="border-t border-gray-100 dark:border-gray-800 my-3" />
					<!-- History List -->
					<div class="space-y-1.5">
						<div v-if="scoresLoading" class="text-center py-6">
							<div class="animate-pulse text-xs text-gray-500 dark:text-gray-400">{{ $t("panel.common.loading") }}</div>
						</div>
						<div v-else-if="scoresHistory.length === 0"
							class="text-center py-6 text-gray-500 dark:text-gray-400">
							<svg class="w-8 h-8 mx-auto mb-1.5 opacity-50" fill="none" stroke="currentColor"
								viewBox="0 0 24 24">
								<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
									d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z">
								</path>
							</svg>
							<p class="text-xs">{{ $t("panel.index.scores.noRecords") }}</p>
						</div>
						<div v-else class="space-y-1">
							<div v-for="item in scoresHistory" :key="item.id"
								class="relative flex items-center justify-between p-2.5 bg-gray-100 dark:bg-gray-800 rounded-sm first:rounded-t-lg last:rounded-b-lg hover:shadow-sm transition">
								<div class="absolute start-0 h-8 w-1 rounded-e-lg"
									:class="item.score > 0 ? 'bg-green-500 dark:bg-green-500' : 'bg-red-500 dark:bg-red-500'">
								</div>
								<div class="flex-1 min-w-0 ms-2">
									<p
										class="text-xs font-medium text-gray-900 dark:text-white mb-0.5 truncate line-clamp-1">
										{{ item.description }}</p>
									<p class="text-[10px] text-gray-500 dark:text-gray-400">
										{{ formatDate(item.created_at) }}
									</p>
								</div>
								<div class="flex items-center gap-1.5 ms-2 flex-shrink-0">
									<div class="text-start">
										<p dir="ltr" class="text-xs font-anjoman font-bold"
											:class="item.score > 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-500 dark:text-red-400'">
											{{ item.score > 0 ? "+" : "" }}{{ item.score.toLocaleString() }}</p>
									</div>
								</div>
							</div>
						</div>
					</div>

					<!-- Per Page and Pagination -->
					<div v-if="!scoresLoading && scoresHistory.length > 0" class="pt-4 space-y-3">
						<div class="flex items-center justify-between">
							<div class="flex items-center gap-2">
								<label class="text-xs text-gray-600 dark:text-gray-400">{{ $t("panel.common.show") }}</label>
								<select v-model="scoresPerPage" @change="changeScoresPerPage"
									class="h-7 font-semibold tracking-wider focus:outline-none bg-gray-50 border border-gray-300 text-gray-900 rounded-lg focus:ring-amber-500 focus:border-amber-500 block p-1.5 text-xs dark:bg-gray-700 dark:border-gray-600 dark:text-white dark:focus:ring-amber-500 dark:focus:border-amber-500">
									<option :value="10">10</option>
									<option :value="20">20</option>
									<option :value="50">50</option>
									<option :value="100">100</option>
								</select>
							</div>
							<div class="text-xs text-gray-600 dark:text-gray-400">
								{{ $t("panel.common.showingRange", { from: (scoresPagination.current_page - 1) * scoresPagination.per_page + 1, to: Math.min(scoresPagination.current_page * scoresPagination.per_page, scoresPagination.total), total: scoresPagination.total }) }}
							</div>
						</div>
						<div v-if="scoresPagination.last_page > 1">
							<PaginationComponent dir="ltr" :pagination="scoresPagination"
								@updatePage="updateScoresPage" />
						</div>
					</div>
				</div>
			</div>
		</BottomSheetDrawer>

	</PanelMasterPage>
</template>

<script>
import PanelMasterPage from "@/views/page/panel/layouts/PanelMasterPage.vue";
import CourseCard3 from "@/views/components/course/CourseCard3.vue";
import CourseCard3Loading from "@/views/components/course/CourseCard3Loading.vue";
import QuestionCard from "@/views/components/discuss/QuestionCard.vue";
import QuestionCardLoading from "@/views/components/discuss/QuestionCardLoading.vue";
import { Swiper, SwiperSlide } from "swiper/vue";
import "swiper/css";
import { Navigation } from "swiper/modules";
import { ref } from "vue";
import axiosInstance from "@/store/axiosInstance";
import AreaChart from "@/views/components/chart/AreaChart.vue";
import DoughnutChart from "@/views/components/chart/DoughnutChart.vue";
import { Countdown } from "vue3-flip-countdown";
import BottomSheetDrawer from "@/views/components/common/BottomSheetDrawer.vue";
import PaginationComponent from "@/views/components/home/PaginationComponent.vue";
import PaymentGatewayList from "@/views/components/payment/PaymentGatewayList.vue";
import { buildPaymentGateways, filterDirectBankGateways, findGatewayById, getDefaultGateway, gatewayRequestPayload } from "@/config/paymentGateways";
import PN from "persian-number";
import { toast } from "vue3-toastify";
import "vue3-toastify/dist/index.css";
export default {
	components: {
		PanelMasterPage,
		Countdown,
		CourseCard3,
		QuestionCard,
		Swiper,
		SwiperSlide,
		CourseCard3Loading,
		QuestionCardLoading,
		AreaChart,
		DoughnutChart,
		BottomSheetDrawer,
		PaginationComponent,
		PaymentGatewayList,
		// Navigation
	},
	data() {
		return {
			direction: ref(import.meta.client ? localStorage.getItem("direction") : null),
			modules: [Navigation],
			courses: {},
			questions: {},
			numberQuestionsThisWeek: 0,
			numberOfCurrentCourse: 0,
			numberOfCompletedCourse: 0,
			numberOfQuesion: 0,
			score: 0,
			scoreOfThisWeek: 0,
			amount: "",
			formattedAmount: "",
			increaseWalletLoading: false,
			selectedGateway: null,
			walletBalance: 0,
			isOpenIncreaseWalletBalanceModal: false,
			watchedTimeThisWeek: 0,
			watchedTimeTotal: 0,
			activePlan: null,
			interval: null,
			loading: false,
			errors: ref(null),
			watchedTimesChart: null,
			purchasedCoursechart: null,
			// Scores Bottom Sheet
			isOpenScoresModal: false,
			scoresActiveTab: "convert",
			scoresTotalScores: 0,
			scoresConversionInfo: {
				conversion_rate: 1,
				min_scores: 1000,
			},
			scoresConvertAmount: null,
			formattedScoresConvertAmount: "",
			scoresConverting: false,
			scoresFilters: {
				type: "",
				search: "",
			},
			scoresHistory: [],
			scoresLoading: false,
			scoresSearchTimeout: null,
			scoresSortBy: "date_desc",
			scoresPagination: {
				current_page: 1,
				last_page: 1,
				per_page: 20,
				total: 0,
			},
			scoresPerPage: 20,
			scoresTotalEarned: 0,
			scoresTotalConverted: 0,
			scoresConversionCount: 0,
			scoresDataLoaded: false,
		};
	},
	computed: {
		gateways() {
			return filterDirectBankGateways(buildPaymentGateways(this.$t));
		},
		days() {
			return Math.floor(this.remainingVip / (60 * 60 * 24));
		},
		hours() {
			return String(Math.floor((this.remainingVip % (60 * 60 * 24)) / (60 * 60))).padStart(2, "0");
		},
		minutes() {
			return String(Math.floor((this.remainingVip % (60 * 60)) / 60)).padStart(2, "0");
		},
		seconds() {
			return String(this.remainingVip % 60).padStart(2, "0");
		},
		amountInWords() {
			return this.amount ? PN.convert(parseInt(this.amount.replace(/,/g, ""))) : "";
		},
		scoresConvertible() {
			return Math.max(0, this.scoresTotalScores);
		},
		scoresProgressPercentage() {
			if (this.scoresTotalEarned === 0) return 0;
			return Math.min(100, (this.scoresTotalScores / this.scoresTotalEarned) * 100);
		},
		redeemableCredit() {
			return Math.floor(this.scoresTotalScores * this.scoresConversionInfo.conversion_rate);
		},
		minConvertibleAmount() {
			return Math.floor(this.scoresConversionInfo.min_scores * this.scoresConversionInfo.conversion_rate);
		},
	},
	methods: {
		getUserData() {
			this.loading = true;
			axiosInstance
				.post("/panel/index")
				.then((response) => {
					// this.userData = response.data.payments;
					this.courses = response.data.courses;
					this.questions = response.data.questions;
					this.numberOfCurrentCourse = response.data.numberOfCurrentCourse;
					this.numberOfCompletedCourse = response.data.numberOfCompletedCourse;
					this.numberOfQuesion = response.data.numberOfQuestion;
					this.score = response.data.score;
					this.scoreOfThisWeek = response.data.score_of_this_week;
					this.numberQuestionsThisWeek = response.data.number_questions_this_week;
					this.walletBalance = response.data.walletBalance;
					this.watchedTimeThisWeek = response.data.watchedTimeThisWeek;
					this.watchedTimeTotal = response.data.watchedTimeTotal;
					this.activePlan = response.data.active_plan;
					this.watchedTimesChart = response.data.watched_times_chart;
					this.purchasedCoursechart = response.data.purchased_course_chart;
				})
				.catch((error) => {
					console.error(error);
				})
				.finally(() => {
					this.loading = false;
				});
		},
		formatSecondsToTime(seconds) {
			const date = new Date(null);
			date.setSeconds(seconds);
			return date.toISOString().substr(11, 8);
		},
		startCountdownVip() {
			this.interval = setInterval(() => {
				if (this.remainingVip > 0) {
					this.remainingVip--;
				} else {
					this.hasVip = false;
					clearInterval(this.interval);
				}
			}, 1000);
		},
		async increaseWalletBalance() {
			this.increaseWalletLoading = true;
			this.errors = null;

			let params = {
				amount: this.amount,
				...gatewayRequestPayload(this.selectedGateway),
			};
			axiosInstance
				.post("/panel/increase-wallet-balance", params)
				.then((response) => {
					window.location.href = response.data.bank_gateway_url;
				})
				.catch((error) => {
					if (error.response.status === 422) {
						this.errors = error.response.data.errors;
					}
					console.error(error.response.data.errors);
				})
				.finally(() => {
					this.increaseWalletLoading = false;
				});
		},
		closeIncreseWalletBalanceModal() {
			this.isOpenIncreaseWalletBalanceModal = false;
			this.amount = "";
			this.formattedAmount = "";
			this.errors = null;
		},
		openIncreseWalletBalanceModal() {
			this.selectedGateway = getDefaultGateway(this.gateways);
			this.isOpenIncreaseWalletBalanceModal = true;
		},
		onInput() {
			const rawNumber = this.formattedAmount.replace(/[^0-9]/g, "");
			this.formattedAmount = rawNumber.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
			this.amount = rawNumber;
		},
		onScoresInput() {
			// حذف کاراکترهای غیر عددی
			let rawNumber = this.formattedScoresConvertAmount.replace(/[^0-9]/g, "");

			// محدود کردن به حداکثر امتیاز قابل تبدیل
			if (rawNumber && parseInt(rawNumber) > this.scoresConvertible) {
				rawNumber = this.scoresConvertible.toString();
			}

			// فرمت کردن با کاما
			this.formattedScoresConvertAmount = rawNumber.replace(/\B(?=(\d{3})+(?!\d))/g, ",");

			// ذخیره مقدار عددی
			this.scoresConvertAmount = rawNumber ? parseInt(rawNumber) : null;
		},
		openScoresModal() {
			this.isOpenScoresModal = true;
			this.scoresActiveTab = "convert";
			// فقط اگر داده‌ها قبلاً load نشده باشند، درخواست بزن
			if (!this.scoresDataLoaded) {
				this.loadScoresData();
			}
		},
		closeScoresModal() {
			this.isOpenScoresModal = false;
			this.scoresConvertAmount = null;
			this.formattedScoresConvertAmount = "";
			// فیلترها را reset نکنیم تا کاربر بتواند فیلترهایش را حفظ کند
		},
		async loadScoresData() {
			await Promise.all([this.loadScoresHistory(), this.loadScoresConversionInfo()]);
			this.scoresDataLoaded = true;
		},
		async loadScoresHistory() {
			this.scoresLoading = true;
			try {
				const params = {
					page: this.scoresPagination.current_page,
					per_page: this.scoresPerPage,
					sort_by: this.scoresSortBy,
					...this.scoresFilters,
				};
				Object.keys(params).forEach((key) => {
					if (params[key] === "" || params[key] === null) {
						delete params[key];
					}
				});
				const response = await axiosInstance.get("/panel/scores", { params });
				if (response.data.success) {
					this.scoresTotalScores = response.data.data.total_scores;
					this.scoresTotalEarned = response.data.data.total_earned;
					this.scoresTotalConverted = response.data.data.total_converted;
					this.scoresConversionCount = response.data.data.conversion_count;
					this.scoresHistory = response.data.data.history;
					this.scoresPagination = response.data.data.pagination;
				}
			} catch (error) {
				console.error("Error loading scores history:", error);
			} finally {
				this.scoresLoading = false;
			}
		},
		async loadScoresConversionInfo() {
			try {
				const response = await axiosInstance.get("/panel/scores/conversion-info");
				if (response.data.success) {
					this.scoresConversionInfo = response.data.data;
				}
			} catch (error) {
				console.error("Error loading conversion info:", error);
			}
		},
		debounceScoresSearch() {
			clearTimeout(this.scoresSearchTimeout);
			this.scoresSearchTimeout = setTimeout(() => {
				this.scoresPagination.current_page = 1;
				this.loadScoresHistory();
			}, 500);
		},
		sortScoresHistory() {
			this.scoresPagination.current_page = 1;
			this.loadScoresHistory();
		},
		updateScoresPage(page) {
			this.scoresPagination.current_page = page;
			this.loadScoresHistory();
		},
		changeScoresPerPage() {
			this.scoresPagination.current_page = 1;
			this.loadScoresHistory();
		},
		async convertScoresToMoney() {
			if (!this.scoresConvertAmount || this.scoresConvertAmount < this.scoresConversionInfo.min_scores || this.scoresConvertAmount > this.scoresTotalScores) {
				return;
			}
			this.scoresConverting = true;
			try {
				const response = await axiosInstance.post("/panel/scores/convert-to-money", {
					scores: this.scoresConvertAmount,
				});
				if (response.data.success) {
					toast.success(response.data.message, {
						theme: "colored",
						hideProgressBar: false,
						rtl: localStorage.getItem("direction") == "rtl" ? true : false,
						bodyClassName: "font-YekanBakh",
						toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
						transition: toast.TRANSITIONS.BOUNCE,
						position: toast.POSITION.BOTTOM_RIGHT,
					});
					this.scoresConvertAmount = null;
					this.formattedScoresConvertAmount = "";
					await this.loadScoresData();
					this.getUserData(); // Refresh wallet balance
				} else {
					toast.warning(response.data.message || this.$t("panel.index.scores.convertError"), {
						theme: "colored",
						hideProgressBar: false,
						rtl: localStorage.getItem("direction") == "rtl" ? true : false,
						bodyClassName: "font-YekanBakh text-gray-800",
						toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
						transition: toast.TRANSITIONS.BOUNCE,
						position: toast.POSITION.BOTTOM_RIGHT,
					});
				}
			} catch (error) {
				console.error("Error converting scores:", error);
				toast.warning(error.response?.data?.message || this.$t("panel.index.scores.convertError"), {
					theme: "colored",
					hideProgressBar: false,
					rtl: localStorage.getItem("direction") == "rtl" ? true : false,
					bodyClassName: "font-YekanBakh text-gray-800",
					toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
					transition: toast.TRANSITIONS.BOUNCE,
					position: toast.POSITION.BOTTOM_RIGHT,
				});
			} finally {
				this.scoresConverting = false;
			}
		},
		formatDate(dateString) {
			const date = new Date(dateString);
			return new Intl.DateTimeFormat("fa-IR", {
				year: "numeric",
				month: "long",
				day: "numeric",
				hour: "2-digit",
				minute: "2-digit",
			}).format(date);
		},
	},
	mounted() {
		document.title = this.$t("panel.index.documentTitle");
		this.selectedGateway = getDefaultGateway(this.gateways);
		this.getUserData();
		this.startCountdownVip();
		document.documentElement.addEventListener("onChangeLanguage", () => {
			var slider = document.querySelector(".swiper");
			if (slider) {
				slider.classList.toggle("swiper-rtl");
				var slides = slider.querySelectorAll(".swiper-slide");
				slides.forEach((slide) => {
					slide.setAttribute("dir", localStorage.getItem("direction"));
				});
			}
		});
	},
	watch: {
		gateways(list) {
			const currentId = this.selectedGateway?.id;
			const resolved = currentId ? findGatewayById(list, currentId) : null;
			const next = resolved || getDefaultGateway(list);
			if (next?.id !== currentId) {
				this.selectedGateway = next;
			}
		},
	},
	beforeUnmount() {
		clearInterval(this.interval);
	},
};
</script>

